const indexByLocale: Record<TranslationLocale, number> = { ja: 0, es: 1, de: 2, zh: 3 };

function dynamicTranslation(locale: TranslationLocale, english: string): string | null {
  const index = indexByLocale[locale];
  const patterns: Array<[RegExp, Translation]> = [
    [/^Last (\d+) days$/, ["過去$1日間", "Últimos $1 días", "Letzte $1 Tage", "最近 $1 天"]],
    [/^Created (.+)$/, ["$1 作成", "Creada el $1", "Erstellt am $1", "创建于 $1"]],
    [/^Updated (.+)$/, ["$1 更新", "Actualizado el $1", "Aktualisiert am $1", "更新于 $1"]],
    [/^([\d.,]+) clicks$/, ["$1回クリック", "$1 clics", "$1 Klicks", "$1 次点击"]],
    [/^Key metrics for the last (\d+) days$/, ["過去$1日間の主要指標", "Métricas clave de los últimos $1 días", "Kennzahlen der letzten $1 Tage", "最近 $1 天主要指标"]],
    [/^QR code for (.+)$/, ["$1のQRコード", "Código QR de $1", "QR-Code für $1", "$1 的二维码"]],
    [/^([\d-]+), (\d+) visit sessions, (\d+) outbound click sessions$/, ["$1、訪問$2セッション、外部クリック$3セッション", "$1, $2 sesiones de visita, $3 sesiones con clic externo", "$1, $2 Besuchssitzungen, $3 Sitzungen mit externem Klick", "$1，$2 个访问会话，$3 个外链点击会话"]],
    [/^Outbound-link analytics are applied to the first (\d+) links in the document\.$/, ["外部リンク分析は文書内の最初の$1件まで適用されます。", "El análisis de enlaces salientes se aplica a los primeros $1 enlaces del documento.", "Die Analyse ausgehender Links gilt für die ersten $1 Links im Dokument.", "外链分析仅应用于文档中的前 $1 个链接。"]],
    [/^(\d+) uploads available$/, ["$1件アップロード可能", "$1 cargas disponibles", "$1 Uploads verfügbar", "可上传 $1 次"]],
    [/^(\d+) of 50 monthly uploads remain(?: until (.+))?\.$/, ["月間50件のうち$1件残っています（$2まで）。", "Quedan $1 de 50 cargas mensuales hasta $2.", "$1 von 50 Monats-Uploads verbleiben bis $2.", "50 次月度上传中剩余 $1 次，有效期至 $2。"]],
  ];
  for (const [pattern, values] of patterns) {
    if (pattern.test(english)) return english.replace(pattern, values[index]);
  }
  return null;
}

export function translate(locale: TranslationLocale, english: string) {
  const value = translations[english];
  return value?.[indexByLocale[locale]] ?? dynamicTranslation(locale, english) ?? english;
}
